package io.github.mrcalzon02.reverievr;
import android.content.Context; import java.util.*;
final class BreakwaterAudio {static BreakwaterAudio instance; static boolean ready=true; final List<Integer> cues=new ArrayList<>(),feedback=new ArrayList<>(); boolean active,suspended,lifecycle,closed; int sessionStarts,sessionStops; BreakwaterAudio(Context c){instance=this;} void setSessionActive(boolean b){if(b!=active){if(b)sessionStarts++;else sessionStops++;active=b;}} void setSuspended(boolean b){suspended=b;} void resumeForLifecycle(){lifecycle=true;} void pauseForLifecycle(){lifecycle=false;} boolean playNativeCue(int id,float left,float right){if(!ready||!active||suspended||!lifecycle||BreakwaterAudioPolicy.cue(id)==null)return false;cues.add(id);return true;} boolean playFeedback(int flags){if(!ready||!active||suspended||!lifecycle)return false;feedback.add(flags);return true;} boolean playShellFeedback(int flags){if(!ready||!active||!lifecycle)return false;feedback.add(flags);return true;} void close(){closed=true;active=false;}}
